/* From Uiverse.io by Yaya12085 - Tags: button, OTP, form, input */
.__UIV_SCOPE__ .form {
  display: flex;
  align-items: center;
  flex-direction: column;
  justify-content: space-around;
  width: 300px;
  background-color: white;
  border-radius: 12px;
  padding: 20px;
}

.__UIV_SCOPE__ .title {
  font-size: 20px;
  font-weight: bold;
  color: black
}

.__UIV_SCOPE__ .message {
  color: #a3a3a3;
  font-size: 14px;
  margin-top: 4px;
  text-align: center
}

.__UIV_SCOPE__ .inputs {
  margin-top: 10px
}

.__UIV_SCOPE__ .inputs input {
  width: 32px;
  height: 32px;
  text-align: center;
  border: none;
  border-bottom: 1.5px solid #d2d2d2;
  margin: 0 10px;
}

.__UIV_SCOPE__ .inputs input:focus {
  border-bottom: 1.5px solid royalblue;
  outline: none;
}

.__UIV_SCOPE__ .action {
  margin-top: 24px;
  padding: 12px 16px;
  border-radius: 8px;
  border: none;
  background-color: royalblue;
  color: white;
  cursor: pointer;
  align-self: end;
}
